// Playwright config. Tests bind to data-testid only and assert through the UI. The app is already
// running (started by bin/e2e), so no webServer here.
import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
  testDir: './specs',
  use: {
    baseURL: process.env.BASE_URL ?? `http://localhost:${process.env.PORT ?? 3000}`,
    // The contract attribute is data-testid — Playwright's default, so no testIdAttribute override
    // needed. Strict awaiting on data-testid presence is the flake guard.
  },
  // Every spec arranges its own data through the screens on a sheet id of its own and reads the
  // audit file filtered by that id, so specs never share data. workers:1 keeps the suite serial
  // against the one shared app, so a failure stays attributable to one spec.
  fullyParallel: false,
  workers: 1,
  reporter: [['list']],
  projects: [
    {
      name: 'chromium',
      use: {
        ...devices['Desktop Chrome'],
        // Headless Chromium needs its own sandbox off and
        // shared memory in /tmp, or renderer/GPU child processes crash. Harmless elsewhere too.
        launchOptions: { args: ['--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu'] },
      },
    },
  ],
});
#!/usr/bin/env bash
# Build, start the whole app, run the Playwright specs present in e2e/specs, then stop.
set -euo pipefail
cd "$(dirname "$0")/.."

export PORT="${PORT:-3000}"
export BASE_URL="http://localhost:${PORT}"
# Known audit file, shared by the app (bin/start) and the specs (support/audit.ts). Absolute.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

# Refuse to run against a server that is not ours: an app left running on $PORT (an earlier
# bin/start that was never stopped, another sandbox) would take the tests and fail them all.
if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then
  echo "bin/e2e: something is already serving on port ${PORT}; stop it (bin/stop) or set PORT to a free port" >&2
  exit 2
fi

bin/build
bin/start
cleanup() { bin/stop || true; }
trap cleanup EXIT

# Wait for readiness (Actuator health), then run the Playwright specs against BASE_URL. A loaded
# machine can take minutes to bring the JVM up; running the specs before it is ready fails every
# one of them for no reason, so wait long and fail loudly rather than run against nothing.
ready=0
for i in $(seq 1 300); do
  if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then ready=1; break; fi
  sleep 1
done
package net.officefloor.hq.app.session;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * Sign-in by name: there is no password, the name is checked and echoed back trimmed, with the user's locale.
 * The signed-in user's locale is read and chosen here too; it is kept per user and is not audited.
 */
@RestController
@Validated
@RequestMapping("/api/session")
public class SessionController {

    public record SignIn(@NotBlank @Size(max = 100) String name) {
    }

    public record User(String name, String locale) {
    }

    public record LocaleForm(@NotNull @Pattern(regexp = "en|de") String locale) {
    }

    public record LocaleView(String locale) {
    }

    private final UserLocaleRepository locales;

    public SessionController(UserLocaleRepository locales) {
        this.locales = locales;
    }

    @PostMapping
    @Transactional(readOnly = true)
    public User signIn(@Valid @RequestBody SignIn request) {
        String name = request.name().trim();
        return new User(name, localeOf(name));
    }

    @GetMapping("/locale")
    @Transactional(readOnly = true)
    public LocaleView locale(@RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return new LocaleView(localeOf(user.trim()));
    }

    @PutMapping("/locale")
    @Transactional
    public LocaleView setLocale(
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody LocaleForm request) {
        String name = user.trim();
        UserLocale chosen = locales.findById(name).orElseGet(() -> new UserLocale(name, request.locale()));
        chosen.setLocale(request.locale());
        locales.save(chosen);
        return new LocaleView(chosen.getLocale());
    }

    private String localeOf(String user) {
        return locales.findById(user).map(UserLocale::getLocale).orElse(UserLocale.DEFAULT);
    }
}
